<script lang="ts">
	import { enhance } from '$app/forms';
	import { onDestroy } from 'svelte';
	import type { PageProps } from './$types';
	let { data, form }: PageProps = $props();
	let view = $state('overview');
	let filter = $state('all');
	let demoState = $state('idle');
	let demoError = $state('');
	let connection: RTCPeerConnection | null = null;
	let stream: MediaStream | null = null;
	let speaker: HTMLAudioElement | null = null;
	let timeout: ReturnType<typeof setTimeout> | null = null;
	const money = (cents: number | null, currency = 'EUR') => cents === null ? '—' : new Intl.NumberFormat('de-DE', { style: 'currency', currency }).format(cents / 100);
	const date = (value: string | null) => value ? new Date(value).toLocaleString('de-DE', { dateStyle: 'short', timeStyle: 'short' }) : '—';
	const labels: Record<string,string> = { pending: 'Wartet', calling: 'Im Gespräch', contacted: 'Kontaktiert', stopped: 'Kontaktstopp', converted: 'Bestellt', expired: 'Abgelaufen',
		reserved: 'Reserviert', dialing: 'Wählt', connected: 'Verbunden', ended: 'Beendet', failed: 'Fehlgeschlagen', unknown: 'Ergebnis prüfen', simulated: 'Simuliert',
		control: 'Kontrollgruppe', treatment: 'Recovery', interested: 'Interessiert', undecided: 'Noch unentschieden', refused: 'Abgelehnt', wrong_person: 'Falsche Person', voicemail: 'Mailbox', human_needed: 'Übergabe', purchased_claimed: 'Kauf angegeben' };
	const r = $derived(data.recovery);
	const checkouts = $derived((r?.checkouts || []).filter((c: any) => filter === 'all' || c.status === filter));
	const admin = $derived(data.user?.role === 'admin');
	function endDemo() {
		if (timeout) clearTimeout(timeout);
		connection?.close(); connection = null;
		stream?.getTracks().forEach((t) => t.stop()); stream = null;
		if (speaker) { speaker.srcObject = null; speaker = null; }
		demoState = 'idle';
	}
	onDestroy(endDemo);
	async function startDemo() {
		demoError = ''; demoState = 'connecting';
		try {
			stream = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true } });
			connection = new RTCPeerConnection();
			const pc = connection;
			speaker = new Audio(); speaker.autoplay = true;
			pc.ontrack = (e) => { if (speaker) { speaker.srcObject = e.streams[0]; void speaker.play(); } };
			stream.getTracks().forEach((track) => pc.addTrack(track, stream!));
			pc.createDataChannel('events');
			pc.onconnectionstatechange = () => {
				if (pc.connectionState === 'connected') demoState = 'connected';
				if (['failed', 'closed', 'disconnected'].includes(pc.connectionState)) endDemo();
			};
			await pc.setLocalDescription(await pc.createOffer());
			const response = await fetch('/recovery/demo', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ sdp: pc.localDescription?.sdp }) });
			const result = await response.json();
			if (!response.ok) throw new Error(result.error || 'Sprachdemo nicht verfügbar.');
			await pc.setRemoteDescription({ type: 'answer', sdp: result.transport.sdp });
			timeout = setTimeout(endDemo, 180000);
		} catch (e) { endDemo(); demoError = e instanceof Error ? e.message : 'Mikrofon oder Verbindung nicht verfügbar.'; }
	}
</script>

<svelte:head><title>Rescova · Cart Recovery</title><meta name="description" content="Abgebrochene Warenkörbe mit persönlichen KI-Gesprächen zurückgewinnen." /></svelte:head>

<div class="recovery-app">
	<aside>
		<a href="/recovery" class="logo" aria-label="Rescova Startseite"><span class="mark">r</span> rescova<span class="logo-dot">.</span></a>
		<div class="workspace"><span class="workspace-icon">A</span><div><strong>Cart Recovery</strong><small>Dein Händler-Workspace</small></div><span>⌄</span></div>
		<p class="nav-label">WORKSPACE</p>
		<nav aria-label="Recovery Navigation">
			{#each [{ id: 'overview', icon: '◫', label: 'Übersicht' }, { id: 'checkouts', icon: '▤', label: 'Warenkörbe' }, { id: 'calls', icon: '◌', label: 'Gespräche' }, { id: 'settings', icon: '⚙', label: 'Agent & Regeln' }] as item}
				<button class:active={view === item.id} onclick={() => view = item.id}><span class="nav-icon">{item.icon}</span>{item.label}{#if item.id === 'checkouts'}<small class="count">{r?.checkouts.length || 0}</small>{/if}</button>
			{/each}
		</nav>
		<div class="sidebar-bottom"><div class="pilot-note"><span class="status-dot"></span> Pilot-Workspace<p>Kontrolliert starten.<br />Mit echten Ergebnissen wachsen.</p></div><a href="/">Rescova Plattform ↗</a><form method="POST" action="/logout"><button>Abmelden</button></form></div>
	</aside>
	<div class="main-wrap">
		<header><span>Workspace <span class="slash">/</span> <strong>Cart Recovery</strong></span><div><span class="pill neutral">Pilot</span><span class="avatar">{data.user?.displayName?.slice(0,1) || 'R'}</span></div></header>
		<main>
			<div class="page-heading"><div><p class="eyebrow">PERSÖNLICHE GESPRÄCHE. NEUE CHANCEN.</p><h1>{view === 'overview' ? 'Jeder Warenkorb hat eine Geschichte.' : view === 'checkouts' ? 'Die nächste Chance liegt schon bereit.' : view === 'calls' ? 'Gespräche, die weiterhelfen.' : 'Deine Marke. Deine Spielregeln.'}</h1><p class="subtitle">{view === 'overview' ? 'Verstehe, was zum Kauf fehlt. Gewinne Kund:innen zurück — mit Rescova.' : 'Alles im Blick. Jede Aktion bleibt unter deiner Kontrolle.'}</p></div><button class="button secondary" onclick={() => view = 'settings'}>Shop einrichten <span>↗</span></button></div>
			{#if form?.error || data.loadError}<p class="notice error" role="alert">{form?.error || data.loadError}</p>{/if}
			{#if form?.success}<p class="notice" role="status">{form.success}</p>{/if}
			{#if r && !r.liveEnabled}<div class="mode-banner"><span class="status-dot"></span><strong>Du bist im sicheren Pilotmodus.</strong><span>Live-Anrufe sind gesperrt. Simulationsdaten lösen keine externen Aktionen aus.</span></div>{/if}
			{#if view === 'overview'}
				<div class="stats">
					<article class="stat"><p>Warenkörbe im Blick <span>↗</span></p><strong>{r?.checkouts.length || 0}</strong><small>Bis zu 100 neueste Checkouts</small></article>
					<article class="stat"><p>Bestellungen bestätigt <span>↗</span></p><strong>{r?.checkouts.filter((c: any) => c.completed_at).length || 0}</strong><small>Vom Shop bestätigt · keine Umsatzzuweisung</small></article>
					<article class="stat"><p>Gespräche <span>◌</span></p><strong>{r?.calls.filter((c: any) => c.status !== 'simulated').length || 0}</strong><small>{r?.calls.filter((c: any) => c.status === 'simulated').length || 0} simulierte Prüfungen separat</small></article>
					<article class="stat"><p>Geschätzte Gesprächskosten</p><strong>{r?.costsByCurrency?.length ? r.costsByCurrency.map((c: any) => money(c.cents, c.currency)).join(' · ') : money(0)}</strong><small>Händlerquote · {r?.costs?.missing || 0} unvollständig erfasst</small></article>
				</div>
				<div class="overview-grid">
					<section class="hero-card"><span class="pill light">DEIN RECOVERY-AGENT</span><h2>Ein gutes Gespräch<br />macht den Unterschied.</h2><p>Der Agent hört zu, klärt offene Fragen und findet heraus, was zum Kauf fehlt. Natürlich, transparent und im Ton deiner Marke.</p><div class="wave" aria-hidden="true">{#each Array(34) as _, i}<i style={`height:${14 + (Math.sin(i * 1.7) + 1) * 24}px`}></i>{/each}</div><div class="demo-bottom"><div><strong>AFTERHOURS</strong><small>Fiktiver Shop · Browser-Sprachdemo</small></div><button class="button" disabled={!admin || !r?.configured.browserDemo || demoState === 'connecting'} onclick={() => demoState === 'connected' ? endDemo() : startDemo()}>{!r?.configured.browserDemo ? 'Demo deaktiviert' : demoState === 'connecting' ? 'Verbinde …' : demoState === 'connected' ? 'Demo beenden ■' : 'Demo sprechen ↗'}</button></div><p class="demo-hint">Mikrofonfreigabe nötig. GPT-Live verarbeitet Audio; die Demo simuliert Produkte und Rabatte. Max. 3 Minuten.</p>{#if demoError}<p role="alert" class="demo-error">{demoError}</p>{/if}</section>
					<section class="panel setup"><div class="section-title"><h2>Bereit für deinen ersten Pilot?</h2><span class="pill neutral">Einrichtung</span></div><p>In wenigen Schritten von der Idee zum Gespräch.</p>{#each [{ n: '01', title: 'Shopify verbinden', text: 'Aktuelle Checkouts, Produkte und Bestellungen.', done: r?.shops.some((s: any) => s.mode === 'live') }, { n: '02', title: 'Agent & Grenzen festlegen', text: 'Markenstimme, Rabatte und Anrufzeiten.', done: r?.shops.some((s: any) => s.approved_at) }, { n: '03', title: 'Kontaktberechtigung prüfen', text: 'Nachweis für genau diesen Kontakt und Zweck.', done: r?.checkouts.some((c: any) => c.has_evidence) }] as step}<div class="setup-step"><span class:done={step.done}>{step.done ? '✓' : step.n}</span><div><strong>{step.title}</strong><p>{step.text}</p></div></div>{/each}<button class="text-button" onclick={() => view = 'settings'}>Einrichtung öffnen <span>→</span></button></section>
				</div>
				<section class="panel"><div class="section-title"><div><h2>Was bringt Recovery zusätzlich?</h2><p>Eine feste Kontrollgruppe trennt zusätzliche Wirkung von Käufen, die ohnehin passiert wären.</p></div><span class="pill neutral">7 Tage Beobachtung</span></div>{#if !r?.experiments.length}<div class="empty-chart"><div class="chart-bars" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div><strong>Noch keine auswertbare Live-Kohorte</strong><p>Simulationsdaten fließen nicht in die Erfolgsmessung ein.</p></div>{:else}{#each r.experiments as exp}<p>{r.shops.find((s: any) => s.id === exp.shopId)?.brand}: zusätzlicher geschätzter Deckungsbeitrag <strong>{money(exp.incrementalContributionCents, exp.currency)}</strong></p><table><thead><tr><th>Gruppe</th><th>Kontakte</th><th>Bestellungen</th><th>Deckungsbeitrag</th></tr></thead><tbody>{#each exp.groups as group}<tr><td>{labels[group.arm]}</td><td>{group.contacts}</td><td>{group.conversions}</td><td>{money(group.netContributionCents, exp.currency)}</td></tr>{/each}</tbody></table><p class="fine-print">{exp.note}</p>{/each}{/if}</section>
				<section class="panel latency"><div><h2>Gesprächsqualität messbar machen.</h2><p>Live-Samples der letzten 7 Tage. Ohne Messung zeigen wir keine erfundenen Werte.</p></div><div class="latency-values">{#each ['response_latency', 'tool_latency'] as kind}{@const metric = r?.latency.find((m: any) => m.kind === kind)}<div><small>{kind === 'response_latency' ? 'Sprache → Agent-Playout' : 'Tool-Ausführung'}</small><strong>{metric ? `${Math.round(metric.p50)} / ${Math.round(metric.p95)} ms` : '— / —'}</strong><small>p50 / p95 · {metric?.samples || 0} Samples</small></div>{/each}</div></section>
			{:else if view === 'checkouts'}
				<section class="panel"><div class="section-title"><h2>Warenkörbe</h2><label class="filter">Status <select bind:value={filter}><option value="all">Alle</option>{#each ['pending', 'converted', 'stopped', 'contacted'] as status}<option value={status}>{labels[status]}</option>{/each}</select></label></div><div class="table-scroll"><table><thead><tr><th>Warenkorb</th><th>Wert</th><th>Status</th><th>Berechtigung</th><th>Aktionen</th></tr></thead><tbody>{#each checkouts as checkout}<tr><td><strong>{checkout.items?.map((i: any) => i.title).join(' + ') || 'Checkout'}</strong><small>•••• {checkout.phone_suffix || 'keine Nummer'} · {date(checkout.source_updated_at)}</small><small>{labels[checkout.arm] || 'Noch keiner Gruppe zugewiesen'}</small></td><td>{money(checkout.subtotal_cents, checkout.currency)}</td><td><span class="pill" class:stopped={checkout.status === 'stopped'}>{labels[checkout.status]}</span><small>{checkout.attempts} Versuch(e)</small></td><td>{checkout.stopped_at ? 'Kontakt gestoppt' : checkout.has_evidence ? `Nachweis bis ${date(checkout.expires_at)}` : 'Nachweis fehlt'}{#if admin && !checkout.stopped_at && !checkout.has_evidence}<details><summary>Nachweis erfassen</summary><form method="POST" action="?/consent" use:enhance class="consent-form"><input type="hidden" name="shopId" value={checkout.shop_id} /><input type="hidden" name="checkoutId" value={checkout.id} /><label>Nachweis / Quelle<textarea name="evidence" minlength="20" maxlength="2000" required></textarea></label><label>Einwilligung am (UTC)<input type="datetime-local" name="consentedAt" required /></label><label>Gültig bis (UTC)<input type="datetime-local" name="expiresAt" required /></label><label>Kontakt-Zeitzone<input name="timezone" value="Europe/Berlin" required /></label><label class="checkbox"><input type="checkbox" name="verified" required /> Ich habe die Einwilligung für KI-Rückrufe zu diesem Checkout geprüft.</label><button class="button">Nachweis speichern</button></form></details>{/if}</td><td>{#if admin}<div class="row-actions"><form method="POST" action="?/call" use:enhance><input type="hidden" name="shopId" value={checkout.shop_id} /><input type="hidden" name="checkoutId" value={checkout.id} /><button class="button small" disabled={!!checkout.stopped_at || !!checkout.completed_at}>{r.shops.find((s: any) => s.id === checkout.shop_id)?.mode === 'simulation' ? 'Simulation prüfen' : 'Anruf anfordern'}</button></form><form method="POST" action="?/stop" use:enhance><input type="hidden" name="shopId" value={checkout.shop_id} /><input type="hidden" name="checkoutId" value={checkout.id} /><button class="text-button danger" disabled={!!checkout.stopped_at}>Kontakt stoppen</button></form></div>{/if}</td></tr>{/each}</tbody></table></div>{#if !checkouts.length}<div class="empty-state">Noch keine passenden Checkouts. Verbinde deinen Shop oder starte die lokalen Fixtures.</div>{/if}</section>
			{:else if view === 'calls'}
				<section class="panel"><div class="section-title"><h2>Gesprächsverlauf</h2><span class="pill neutral">50 neueste Versuche</span></div><div class="table-scroll"><table><thead><tr><th>Zeitpunkt</th><th>Status</th><th>Ergebnis</th><th>Zusammenfassung</th><th>Kosten (geschätzt)</th></tr></thead><tbody>{#each r?.calls || [] as call}<tr><td>{date(call.created_at)}</td><td><span class="pill">{labels[call.status]}</span></td><td>{labels[call.outcome] || call.outcome || '—'}</td><td>{call.summary || 'Noch kein bestätigtes Gesprächsergebnis.'}</td><td>{money(call.cost_cents, call.currency)}</td></tr>{/each}</tbody></table></div>{#if !r?.calls.length}<div class="empty-state">Hier erscheinen echte Gesprächsergebnisse und separat gekennzeichnete Simulationen.</div>{/if}</section>
			{:else}
				<section class="panel connect"><div><h2>Deinen Shopify-Shop verbinden</h2><p>OAuth hält Shop-Zugangsdaten auf dem Server. Die Verbindung aktiviert noch keine Anrufe.</p></div><form method="POST" action="?/connect"><label class="sr-only" for="shop-domain">Shop-Domain</label><input id="shop-domain" name="domain" value={r?.configured.testShopDomain || ''} placeholder="dein-shop.myshopify.com" required pattern="[a-z0-9][a-z0-9-]*\.myshopify\.com" /><button class="button" disabled={!admin || !r?.configured.shopify}>Shopify verbinden ↗</button></form>{#if !r?.configured.shopify}<p class="fine-print">Shopify-App-Zugang und registrierter Callback fehlen noch in der lokalen Konfiguration.</p>{/if}</section>
				{#each r?.shops || [] as shop}<section class="panel"><div class="section-title"><div><h2>{shop.brand}</h2><p>{shop.domain} · {shop.currency}</p></div><span class="pill neutral">{shop.mode === 'simulation' ? 'Simulation' : 'Shopify verbunden'}</span></div><form method="POST" action="?/settings" use:enhance class="settings-form"><input type="hidden" name="shopId" value={shop.id} /><div class="form-grid"><label>Markenname<input name="brand" value={shop.brand} maxlength="100" required disabled={!admin} /></label><label>Markenstimme<textarea name="brand_voice" maxlength="2000" disabled={!admin}>{shop.brand_voice}</textarea></label></div><details><summary>Anrufzeiten, Limits und Angebotsregeln bearbeiten</summary>
<p class="fine-print">Zeitfenster gelten in der geprüften Zeitzone des Kontakts. Cent-Beträge beziehen sich auf {shop.currency}. Preise, Verfügbarkeit und Rabatte werden vor jeder Aktion neu geprüft.</p>
<div class="form-grid"><label>Beginn der Anrufzeit<input type="time" name="start" value={shop.rules.start} required disabled={!admin} /></label><label>Ende der Anrufzeit<input type="time" name="end" value={shop.rules.end} required disabled={!admin} /></label></div>
<fieldset><legend>Anruftage</legend><div class="weekdays">{#each ['Mo','Di','Mi','Do','Fr','Sa','So'] as day, i}<label class="checkbox"><input type="checkbox" name="weekdays" value={i+1} checked={shop.rules.weekdays.includes(i+1)} disabled={!admin} />{day}</label>{/each}</div></fieldset>
<label>Standard-Zeitzone<input name="timezone" value={shop.rules.timezone} required disabled={!admin} /></label>
<div class="form-grid">{#each [
{ key:'delayMinutes', label:'Mindestabstand zur letzten Checkout-Änderung (Minuten, 0 = sofort)', min:0, max:1440 },
{ key:'maxAttempts', label:'Maximale Versuche pro Kontakt', min:1, max:3 },
{ key:'cooldownHours', label:'Abstand zwischen Versuchen (Stunden)', min:24, max:168 },
{ key:'expiryDays', label:'Warenkorb höchstens so alt (Tage)', min:1, max:14 },
{ key:'maxDiscountPercent', label:'Maximal erlaubter Rabatt (%)', min:0, max:100 },
{ key:'minSubtotalCents', label:'Mindestwarenwert für Rabatt (Cent)', min:0, max:10000000 },
{ key:'offerHours', label:'Angebotsgültigkeit (Stunden)', min:1, max:72 },
{ key:'holdoutPercent', label:'Kontrollgruppe (%)', min:10, max:50 },
{ key:'contributionPercent', label:'Geschätzter Deckungsbeitrag (%)', min:0, max:100 },
{ key:'voiceCentsPerMinute', label:'Geschätzte Gesamtkosten je Gesprächsminute (Cent)', min:0, max:10000 }
] as field}<label>{field.label}<input type="number" name={field.key} min={field.min} max={field.max} step="1" value={shop.rules[field.key]} required disabled={!admin} /></label>{/each}</div>
</details><label class="checkbox"><input type="checkbox" name="enabled" checked={shop.enabled} disabled={!admin} /> Recovery für diesen Shop aktivieren</label><label class="checkbox"><input type="checkbox" name="approval" disabled={!admin} /> Ich gebe diese Regeln als Händler frei und habe den Kontaktprozess geprüft.</label><div class="settings-bottom"><span>{shop.approved_at ? `Freigegeben am ${date(shop.approved_at)}` : 'Noch keine Händlerfreigabe'}</span><button class="button" disabled={!admin}>Einstellungen speichern</button></div></form>{#if shop.mode === 'live' && !shop.webhooks_ready}<form method="POST" action="?/webhooks" use:enhance class="sync"><input type="hidden" name="shopId" value={shop.id} /><span>Ereignisempfang noch nicht eingerichtet. Eine öffentliche HTTPS-Adresse muss konfiguriert sein.</span><button class="button secondary small" disabled={!admin}>Webhooks einrichten</button></form>{/if}<form method="POST" action="?/sync" use:enhance class="sync"><input type="hidden" name="shopId" value={shop.id} /><span>Letzter Abgleich: {date(shop.sync_at)} {shop.last_error ? `· ${shop.last_error}` : ''}</span><button class="button secondary small" disabled={!admin}>Shop-Daten abgleichen</button></form></section>{/each}
				<section class="panel"><h2>Verbindungen & Freigaben</h2><div class="connections">{#each [{ label: 'Shopify-App', ready: r?.configured.shopify }, { label: 'LiveKit + Twilio', ready: r?.configured.telephony }, { label: 'SMS-Versand', ready: r?.configured.sms }, { label: 'Live-Betrieb', ready: r?.liveEnabled }] as item}<div><span>{item.label}</span><span class="pill neutral">{item.ready ? 'Konfiguriert' : 'Noch gesperrt'}</span></div>{/each}</div><p class="fine-print">Konfiguriert bedeutet nicht live geprüft. Provider-, Audio- und rechtliche Freigabe sind vor einem echten Pilot erforderlich.</p></section>
			{/if}
			<footer>rescova · Persönlich im Gespräch. Verlässlich in der Ausführung.<span>GPT-Live · LiveKit · Twilio</span></footer>
		</main>
	</div>
</div>

<style>
	:global(body){margin:0;background:#f8f9fb;color:#15231c;font-family:Inter,system-ui,sans-serif} :global(*){box-sizing:border-box} .recovery-app{display:flex;min-height:100vh;font-size:14px}aside{position:fixed;inset:0 auto 0 0;width:246px;background:#fff;border-right:1px solid #e8ebe9;padding:33px 22px;display:flex;flex-direction:column;z-index:10}.logo{display:flex;align-items:center;font-size:30px;font-weight:650;letter-spacing:-1.5px;text-decoration:none;color:#18291f;gap:7px}.mark{background:#296443;color:white;border-radius:10px;font-size:30px;font-weight:700;width:34px;height:36px;display:grid;place-content:center;font-style:italic}.logo-dot{color:#47875d;margin-left:-6px}.workspace{margin:39px 0 32px;padding:12px 8px;border:1px solid #e7ebe8;border-radius:9px;display:flex;align-items:center;gap:9px}.workspace-icon{width:32px;height:32px;background:#e9eee9;border-radius:7px;display:grid;place-content:center;color:#46654d;font-weight:600}.workspace strong{font-size:12px}.workspace small{display:block;font-size:10px;color:#8a918d;margin-top:4px}.workspace>span:last-child{margin-left:auto;color:#929d95}.nav-label{font-size:10px;letter-spacing:1.1px;color:#9aA49e;margin:0 12px 14px}nav button{display:flex;align-items:center;width:100%;padding:13px 12px;background:none;border:0;border-radius:8px;gap:11px;color:#77827b;font:inherit;cursor:pointer;text-align:left;margin:4px 0}nav button.active{background:#edf4ed;color:#346143;font-weight:600}.nav-icon{font-size:20px;line-height:18px;width:20px}.count{margin-left:auto;background:#dce9dc;color:#47724e;padding:3px 7px;border-radius:5px;font-size:10px}.sidebar-bottom{margin-top:auto;padding-top:50px}.pilot-note{border:1px solid #e4eae4;border-radius:9px;padding:14px;font-weight:600;font-size:11px}.pilot-note p{font-weight:400;color:#8b948d;line-height:1.8;margin-bottom:0}.status-dot{width:7px;height:7px;border-radius:50%;background:#558a5e;display:inline-block;margin-right:7px;flex-shrink:0}.sidebar-bottom>a,.sidebar-bo